create table nothingsports_fixture_read_private.global_encoded_rows(source_id text not null,fixture_id text not null,base jsonb,identity_keys text[],base_hash text not null,base_updated_at timestamptz not null,score jsonb,score_hash text,first_complete timestamptz,receipt_s text,receipt_t text,base_schema text not null,projector_schema text not null,parser_schema text not null,render_timezone text,rendered_at timestamptz,can_encode boolean not null,row_text text,primary key(source_id,fixture_id),foreign key(source_id,fixture_id) references public.nothingsports_fixture_current(source_id,fixture_id) on delete cascade deferrable initially deferred,check((can_encode and row_text is not null and render_timezone is not null and rendered_at is not null) or(not can_encode and row_text is null and render_timezone is null and rendered_at is null)));
alter table nothingsports_fixture_read_private.global_encoded_rows enable row level security;
revoke all on nothingsports_fixture_read_private.global_encoded_rows from public,anon,authenticated,service_role;
grant select on nothingsports_fixture_read_private.global_encoded_rows to service_role;
create or replace function nothingsports_fixture_read_private.mark_integrity_pending() returns trigger
language plpgsql security definer set search_path='' as $mark$
begin
 if tg_table_name='nothingsports_fixture_sources' and tg_op='UPDATE' then
  if old.discovery_report->'_fixtureObservations' is not distinct from new.discovery_report->'_fixtureObservations' then return null;end if;
 elsif tg_table_name='nothingsports_live_scores' and tg_op='UPDATE' then
  if row(old.source_id,old.fixture_id,old.score,old.content_hash,old.first_completed_at) is not distinct from row(new.source_id,new.fixture_id,new.score,new.content_hash,new.first_completed_at) then return null;end if;
 end if;
 if tg_op<>'INSERT' then insert into nothingsports_fixture_read_private.integrity_pending(source_id) values(old.source_id) on conflict do nothing;end if;
 if tg_op<>'DELETE' then insert into nothingsports_fixture_read_private.integrity_pending(source_id) values(new.source_id) on conflict do nothing;end if;
 return null;
end;$mark$;

create or replace function nothingsports_fixture_read_private.enforce_pending_integrity() returns trigger
language plpgsql security definer set search_path='' as $enforce$
declare base_version text;projector_version text;parser_version text;
begin
 if not exists(select 1 from nothingsports_fixture_read_private.integrity_pending where source_id=new.source_id) then return null;end if;
 -- Existing pending PK serializes this owner. Do not invert pending->source locks here.
 if not nothingsports_fixture_read_private.source_index_complete(new.source_id) then
  raise exception using errcode='23514',message='Fixture index integrity is incomplete; canonical transaction refused';
 end if;
 select md5(pg_get_expr(d.adbin,d.adrelid)) into base_version from pg_attribute a join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
 where a.attrelid='public.nothingsports_fixture_current'::regclass and a.attname='global_fixture' and not a.attisdropped and a.attgenerated='s' and a.atttypid='jsonb'::regtype;
 select md5(pg_get_functiondef(to_regprocedure('public.nothingsports_project_fixture_observations(jsonb,jsonb,jsonb,timestamptz)'))),md5(pg_get_functiondef(to_regprocedure('public.nothingsports_fixture_observation_time(text)'))) into projector_version,parser_version;
 if base_version is distinct from 'd7d2f883cba24dc54897fe44f9930365' or projector_version is distinct from '44d1edfc00ada08fad8deb987472ad54' or parser_version is distinct from '13842433b7af056a35c01e8b234ae3c9' then
  -- Derived encodings must never block accepted canonical facts on version drift.
  delete from nothingsports_fixture_read_private.global_encoded_rows where source_id=new.source_id;
 else
  with source_receipts as materialized (select source_id,discovery_report->'_fixtureObservations' receipts from public.nothingsports_fixture_sources where source_id=new.source_id), inputs as materialized (
   select c.source_id,c.fixture_id,c.global_fixture base,c.identity_keys,c.content_hash base_hash,c.updated_at base_updated_at,
    s.score,s.content_hash score_hash,s.first_completed_at first_complete,src.receipts->c.fixture_id receipt,
    (src.receipts->c.fixture_id)->>'s' receipt_s,(src.receipts->c.fixture_id)->>'t' receipt_t,
    array[s.score->>'scoreCheckedAt',c.global_fixture->>'scoreCheckedAt',s.score->>'statusCheckedAt',c.global_fixture->>'statusCheckedAt',(src.receipts->c.fixture_id)->>'s',(src.receipts->c.fixture_id)->>'t'] raw
   from public.nothingsports_fixture_current c join source_receipts src using(source_id)
   left join public.nothingsports_live_scores s using(source_id,fixture_id)
   left join nothingsports_fixture_read_private.global_encoded_rows w using(source_id,fixture_id)
   where c.source_id=new.source_id and (w.source_id is null or not w.can_encode or
    row(w.base,w.identity_keys,w.base_hash,w.base_updated_at,w.score,w.score_hash,w.first_complete,w.receipt_s,w.receipt_t,w.base_schema,w.projector_schema,w.parser_schema)
    is distinct from row(c.global_fixture,c.identity_keys,c.content_hash,c.updated_at,s.score,s.content_hash,s.first_completed_at,(src.receipts->c.fixture_id)->>'s',(src.receipts->c.fixture_id)->>'t',base_version,projector_version,parser_version))
  ), parsed as materialized (
   select value,public.nothingsports_fixture_observation_time(value) stamp from(select distinct unnest(raw) value from inputs) q where value is not null
  ), eligible as materialized (
   select i.*,not exists(select 1 from unnest(i.raw) r(value) join parsed p using(value) where p.stamp is null) can_encode from inputs i
  )
  insert into nothingsports_fixture_read_private.global_encoded_rows(source_id,fixture_id,base,identity_keys,base_hash,base_updated_at,score,score_hash,first_complete,receipt_s,receipt_t,base_schema,projector_schema,parser_schema,render_timezone,rendered_at,can_encode,row_text)
  select e.source_id,e.fixture_id,e.base,e.identity_keys,e.base_hash,e.base_updated_at,e.score,e.score_hash,e.first_complete,e.receipt_s,e.receipt_t,base_version,projector_version,parser_version,case when e.can_encode then current_setting('TimeZone') end,case when e.can_encode then statement_timestamp() end,e.can_encode,
   case when e.can_encode then (select row_to_json(p)::text from(select e.source_id,e.fixture_id,e.identity_keys,public.nothingsports_project_fixture_observations(e.base,e.score,e.receipt,e.first_complete) fixture)p) else null end
  from eligible e
  on conflict(source_id,fixture_id) do update set base=excluded.base,identity_keys=excluded.identity_keys,base_hash=excluded.base_hash,base_updated_at=excluded.base_updated_at,score=excluded.score,score_hash=excluded.score_hash,first_complete=excluded.first_complete,receipt_s=excluded.receipt_s,receipt_t=excluded.receipt_t,base_schema=excluded.base_schema,projector_schema=excluded.projector_schema,parser_schema=excluded.parser_schema,render_timezone=excluded.render_timezone,rendered_at=excluded.rendered_at,can_encode=excluded.can_encode,row_text=excluded.row_text
  where row(global_encoded_rows.base,global_encoded_rows.identity_keys,global_encoded_rows.base_hash,global_encoded_rows.base_updated_at,global_encoded_rows.score,global_encoded_rows.score_hash,global_encoded_rows.first_complete,global_encoded_rows.receipt_s,global_encoded_rows.receipt_t,global_encoded_rows.base_schema,global_encoded_rows.projector_schema,global_encoded_rows.parser_schema,global_encoded_rows.render_timezone,global_encoded_rows.can_encode,global_encoded_rows.row_text)
   is distinct from row(excluded.base,excluded.identity_keys,excluded.base_hash,excluded.base_updated_at,excluded.score,excluded.score_hash,excluded.first_complete,excluded.receipt_s,excluded.receipt_t,excluded.base_schema,excluded.projector_schema,excluded.parser_schema,excluded.render_timezone,excluded.can_encode,excluded.row_text);
 end if;
 delete from nothingsports_fixture_read_private.integrity_pending where source_id=new.source_id;
 return null;
end;$enforce$;

create trigger encoded_row_score_pending after insert or update or delete on public.nothingsports_live_scores
for each row execute function nothingsports_fixture_read_private.mark_integrity_pending();
create trigger encoded_row_receipt_pending after update of discovery_report on public.nothingsports_fixture_sources
for each row execute function nothingsports_fixture_read_private.mark_integrity_pending();
